    probs = torch.sigmoid(logits).flatten(1)
    targets = targets.flatten(1).float()
    inter = (probs * targets).sum(1)
    return 1 - ((2 * inter + eps) / (probs.sum(1) + targets.sum(1) + eps)).mean()

